/** The Rust engine as WebAssembly (`crates/loci-web`, generated by `scripts/build-wasm.sh`). */
declare module '@loci-web' {
  export class WebEngine {
    private constructor();
    free(): void;
    call(method: string, argsJson: string, bytes?: Uint8Array | null, onProgress?: ((p: { phase: string; done: number; total: number }) => void) | null): unknown;
    static open(persistent: boolean): Promise<WebEngine>;
    readonly persistent: boolean;
  }
  export default function init(input?: { module_or_path?: unknown } | unknown): Promise<unknown>;
}
